compromiseByFingerprint(fingerprint: string, source: string = 'webhook'): boolean {
    // fingerprint должен быть либо key.id, либо key.fingerprint (SHA-256)
    const matches = this.registry.getKeys().filter(
        (k) => k.id === fingerprint || k.fingerprint === fingerprint,
    );
    if (matches.length === 0) return false;
    for (const k of matches) {
        this.compromiseKey(k.id, source);
    }
    return true;
